def check_digit(s):
    if len(s) == 7:
        s = ' ' + s
    total = 0
    for ch, w in zip(s, range(9, 1, -1)):
        v = 36 if ch == ' ' else (ord(ch) - 55 if ch.isalpha() else int(ch))
        total += v * w
    d = 11 - total % 11
    return '0' if d == 11 else ('A' if d == 10 else str(d))
