def add_parity(code, mode):
    ones = code.count('1')
    if mode == 'even':
        return code + ('1' if ones % 2 else '0')
    return code + ('0' if ones % 2 else '1')

def passes(code, mode):
    odd = code.count('1') % 2 == 1
    return odd if mode == 'odd' else not odd

